  <title>Terms Consent</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-alt: #f8fafc;
      --text: #0f172a;
      --muted: #475569;
      --border: #d8e0ea;
      --accent: #2563eb;
      --accent-strong: #1d4ed8;
      --focus: #0f62fe;
      --success-bg: #ecfdf3;
      --success-text: #166534;
      --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #e8f0ff 0%, transparent 34%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      color: var(--text);
      text-decoration: none;
      box-shadow: var(--shadow);
      transform: translateY(-200%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--focus);
      outline-offset: 2px;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 4rem 1.25rem;
    }

    .card {
      width: min(100%, 34rem);
      background: rgba(255, 255, 255, 0.9);
      backdrop-filter: blur(10px);
      border: 1px solid var(--border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 4vw, 2.25rem);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.6rem, 3vw, 2.25rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .subtitle {
      margin: 0 0 1.5rem;
      color: var(--muted);
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      padding: 1rem;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: var(--surface-alt);
    }

    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
    }

    input[type="checkbox"] {
      width: 1.15rem;
      height: 1.15rem;
      margin: 0.2rem 0 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    label {
      display: block;
      font-weight: 600;
      color: var(--text);
      cursor: pointer;
    }

    .required-indicator {
      color: var(--accent-strong);
      margin-left: 0.15em;
    }

    .help-text {
      margin: 0.35rem 0 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.875rem 1.25rem;
      min-width: 10rem;
      background: linear-gradient(180deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.24);
    }

    button:hover {
      filter: brightness(1.03);
    }

    button:focus-visible,
    input[type="checkbox"]:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      font-size: 0.95rem;
      color: var(--success-text);
    }

    .status[data-state="error"] {
      color: #b42318;
    }

    .status[data-state="success"] {
      padding: 0.75rem 1rem;
      border-radius: 12px;
      background: var(--success-bg);
    }

    @media (forced-colors: active) {
      body,
      .card,
      .form-field,
      .skip-link {
        forced-color-adjust: auto;
        background: Canvas;
        color: CanvasText;
        border-color: CanvasText;
        box-shadow: none;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonText;
        box-shadow: none;
      }

      input[type="checkbox"] {
        accent-color: auto;
      }

      .status[data-state="success"] {
        background: Canvas;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Agree to the terms</h1>
      <p class="subtitle">Please review and confirm your consent to continue.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="terms"
              name="terms"
              type="checkbox"
              required
              aria-describedby="terms-help form-status">
            <div>
              <label for="terms">I agree to the Terms of Use <span class="required-indicator" aria-hidden="true">*</span></label>
              <p class="help-text" id="terms-help">You must accept the terms before submitting.</p>
            </div>
          </div>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
        </div>

        <p class="status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("consent-form");
    const checkbox = document.getElementById("terms");
    const status = document.getElementById("form-status");

    form.addEventListener("submit", (event) => {
      if (!checkbox.checked) {
        event.preventDefault();
        checkbox.setAttribute("aria-invalid", "true");
        checkbox.focus();
        status.textContent = "Please agree to the Terms of Use to continue.";
        status.dataset.state = "error";
        return;
      }

      event.preventDefault();
      checkbox.removeAttribute("aria-invalid");
      status.textContent = "Thanks — your consent has been recorded.";
      status.dataset.state = "success";
      form.reset();
    });

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        checkbox.removeAttribute("aria-invalid");
        status.textContent = "";
        status.removeAttribute("data-state");
      }
    });
  </script>
</body>
</html>
